package tr.arcteknik.depo.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Bütün ikonlar Reicon'dan (github.com/dqev/reicon, MIT) alındı; yol verisi değiştirilmedi.
 * Polyline olanlar (chevron) aynı noktalarla path'e çevrildi.
 */
object Ic {
    private class P(val d: String, val stroke: Boolean = false)

    private fun icon(name: String, vararg paths: P): ImageVector {
        val b = ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f)
        for (p in paths) {
            val nodes = PathParser().parsePathString(p.d).toNodes()
            if (p.stroke) {
                b.addPath(
                    pathData = nodes,
                    stroke = SolidColor(Color.Black),
                    strokeLineWidth = 1.5f,
                    strokeLineCap = StrokeCap.Round,
                    strokeLineJoin = StrokeJoin.Round,
                )
            } else {
                b.addPath(pathData = nodes, fill = SolidColor(Color.Black), pathFillType = PathFillType.EvenOdd)
            }
        }
        return b.build()
    }

